import json
import logging
import sys
from pathlib import Path
from typing import Dict, List, Any, Optional

import numpy as np

from code.config import get_logger, DATA_PROCESSED_PATH, DATA_FIGURES_PATH

logger = get_logger(__name__)


def load_segregation_profiles(path: Optional[Path] = None) -> List[Dict[str, Any]]:
    """Load segregation profiles from the JSON file generated by T018."""
    if path is None:
        path = DATA_PROCESSED_PATH / "segregation_profiles.json"

    if not path.exists():
        raise FileNotFoundError(f"Segregation profiles file not found: {path}")

    with open(path, "r") as f:
        data = json.load(f)

    if isinstance(data, dict) and "profiles" in data:
        return data["profiles"]
    elif isinstance(data, list):
        return data
    else:
        raise ValueError(f"Unexpected data format in {path}: expected list or dict with 'profiles' key")


def prepare_heatmap_data(
    profiles: List[Dict[str, Any]],
    target_element: str = "Cr",
    systems: Optional[List[str]] = None,
) -> tuple[np.ndarray, np.ndarray, np.ndarray, List[str], List[float]]:
    """
    Prepare data for a heatmap: segregation energy vs. bulk composition and temperature.

    Args:
        profiles: List of segregation profile dictionaries.
        target_element: The solute element to visualize (e.g., "Cr").
        systems: Optional list of system names to include (e.g., ["Fe-Cr-Mo", "Fe-Cr-V"]).

    Returns:
        Tuple of (unique_temps, unique_concs, energies, system_names, conc_values)
        where energies is a 2D array (len(temps) x len(concs)).
    """
    temps_set = set()
    concs_set = set()
    data_points = []

    for profile in profiles:
        sys_name = profile.get("system", "Unknown")
        if systems and sys_name not in systems:
            continue

        # Expected structure based on T018 output:
        # {
        #   "system": "Fe-Cr-Mo",
        #   "solute": "Cr",
        #   "temperature_K": 800,
        #   "bulk_concentration": 0.05,
        #   "segregation_energy_eV": 0.15,
        #   ...
        # }

        temp = profile.get("temperature_K")
        conc = profile.get("bulk_concentration")
        energy = profile.get("segregation_energy_eV")
        solute = profile.get("solute")

        if temp is None or conc is None or energy is None:
            logger.warning(f"Skipping incomplete profile: {profile}")
            continue

        if solute != target_element:
            continue

        temps_set.add(temp)
        concs_set.add(round(conc, 4))  # Round for grouping
        data_points.append((temp, conc, energy, sys_name))

    if not data_points:
        raise ValueError(f"No data points found for solute={target_element} in systems={systems}")

    unique_temps = sorted(list(temps_set))
    unique_concs = sorted(list(concs_set))

    # Create 2D array: rows = temps, cols = concs
    energies = np.full((len(unique_temps), len(unique_concs)), np.nan)
    system_names = []

    for i, temp in enumerate(unique_temps):
        for j, conc in enumerate(unique_concs):
            # Find matching data point
            matching = [
                d for d in data_points
                if d[0] == temp and abs(d[1] - conc) < 1e-6
            ]
            if matching:
                # Take the first match (or average if multiple exist for same system)
                energies[i, j] = matching[0][2]
                system_names.append(matching[0][3])

    return np.array(unique_temps), np.array(unique_concs), energies, unique_concs, unique_temps


def generate_segregation_heatmap(
    energies: np.ndarray,
    temps: np.ndarray,
    concs: np.ndarray,
    output_path: Optional[Path] = None,
    cmap: str = "viridis",
    title: str = "Segregation Energy vs. Bulk Composition and Temperature",
) -> Path:
    """
    Generate a heatmap visualization of segregation energy.

    Args:
        energies: 2D array of segregation energies (temps x concs).
        temps: Array of temperature values (y-axis).
        concs: Array of concentration values (x-axis).
        output_path: Path to save the figure. Defaults to DATA_FIGURES_PATH / "segregation_heatmap.png".
        cmap: Matplotlib colormap name.
        title: Plot title.

    Returns:
        Path to the saved figure.
    """
    import matplotlib.pyplot as plt
    from matplotlib.colors import Normalize

    if output_path is None:
        output_path = DATA_FIGURES_PATH / "segregation_heatmap.png"

    # Ensure output directory exists
    output_path.parent.mkdir(parents=True, exist_ok=True)

    if energies.size == 0 or np.all(np.isnan(energies)):
        raise ValueError("No valid energy data to plot. Check input data.")

    plt.figure(figsize=(10, 8))

    # Use Normalize for symmetric range if data contains negative values
    vmin = np.nanmin(energies)
    vmax = np.nanmax(energies)
    norm = Normalize(vmin=vmin, vmax=vmax)

    # Create heatmap
    # Note: plt.imshow expects (rows, cols) = (temps, concs)
    # We want temps on y-axis (inverted to have low temp at bottom) and concs on x-axis
    im = plt.imshow(
        energies,
        extent=[concs[0], concs[-1], temps[0], temps[-1]],
        aspect="auto",
        origin="lower",
        cmap=cmap,
        norm=norm,
        interpolation="nearest",
    )

    plt.colorbar(im, label="Segregation Energy (eV)")
    plt.xlabel("Bulk Concentration (at. fraction)")
    plt.ylabel("Temperature (K)")
    plt.title(title)

    # Save figure
    plt.tight_layout()
    plt.savefig(output_path, dpi=300, bbox_inches="tight")
    plt.close()

    logger.info(f"Heatmap saved to: {output_path}")
    return output_path


def main():
    """
    Main entry point for generating the segregation heatmap.
    Loads data from data/processed/segregation_profiles.json and saves to data/figures/segregation_heatmap.png.
    """
    logger.info("Starting heatmap generation (T024b)...")

    try:
        # Load profiles
        profiles = load_segregation_profiles()
        logger.info(f"Loaded {len(profiles)} segregation profiles.")

        # Prepare data for heatmap (default to Cr, all systems)
        # We need to determine which systems and solutes are present
        # For simplicity, we'll iterate over unique solutes and systems if needed
        # But the task specifies a single heatmap, so we'll aggregate or pick the primary one.
        # Let's aggregate all data points into one heatmap for the most common solute.

        # Get unique solutes
        solutes = list(set(p.get("solute") for p in profiles if p.get("solute")))
        if not solutes:
            raise ValueError("No solute information found in profiles.")

        # Pick the first solute (or "Cr" if present)
        target_solute = "Cr" if "Cr" in solutes else solutes[0]
        logger.info(f"Generating heatmap for solute: {target_solute}")

        # Get unique systems
        systems = list(set(p.get("system") for p in profiles if p.get("system")))
        logger.info(f"Systems included: {systems}")

        temps, concs, energies, _, _ = prepare_heatmap_data(
            profiles, target_element=target_solute, systems=systems
        )

        # Generate heatmap
        output_path = generate_segregation_heatmap(
            energies=energies,
            temps=temps,
            concs=concs,
            title=f"Segregation Energy ({target_solute}) vs. Bulk Composition and Temperature",
        )

        logger.info(f"T024b completed successfully. Output: {output_path}")
        return 0

    except FileNotFoundError as e:
        logger.error(f"Input file not found: {e}")
        raise
    except ValueError as e:
        logger.error(f"Data processing error: {e}")
        raise
    except Exception as e:
        logger.exception(f"Unexpected error during heatmap generation: {e}")
        raise


if __name__ == "__main__":
    sys.exit(main())
